/**
 * Gmail Node - Version 2
 * Discriminator: resource=message, operation=get
 */


interface Credentials {
  googleApi: CredentialReference;
  gmailOAuth2: CredentialReference;
}

export type GmailV2MessageGetParams = {
  resource: 'message';
  operation: 'get';
  authentication?: 'oAuth2' | 'serviceAccount' | Expression<string>;
/**
 * Message ID
 */
    messageId: string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint Keep true by default. When true, returns lightweight metadata (labels, subject, from, to, snippet). When false, fetches and parses the full raw email (adds html, text, textAsHtml, headers, attachments), which uses much more memory and is a common cause of out-of-memory crashes. Only set false when the email body is actually required, e.g. for AI classification, summarization, or content processing.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
/**
 * Options
 * @displayOptions.hide { simple: [true] }
 * @default {}
 */
    options?: {
    /** Prefix for name of the binary property to which to write the attachment. An index starting with 0 will be added. So if name is 'attachment_' the first attachment is saved to 'attachment_0'.
     * @default attachment_
     */
    dataPropertyAttachmentsPrefixName?: string | Expression<string>;
    /** Whether the email's attachments will be downloaded and included in the output
     * @default false
     */
    downloadAttachments?: boolean | Expression<boolean>;
  };
};

export type GmailV2MessageGetOutput = {
  date?: string;
  from?: {
    html?: string;
    text?: string;
    value?: Array<{
      address?: string;
      name?: string;
    }>;
  };
  headers?: {
    'arc-authentication-results'?: string;
    'arc-message-signature'?: string;
    'arc-seal'?: string;
    'authentication-results'?: string;
    'content-type'?: string;
    date?: string;
    'delivered-to'?: string;
    'dkim-signature'?: string;
    from?: string;
    'message-id'?: string;
    'mime-version'?: string;
    received?: string;
    'received-spf'?: string;
    'return-path'?: string;
    subject?: string;
    to?: string;
    'x-google-smtp-source'?: string;
    'x-received'?: string;
  };
  id?: string;
  labelIds?: Array<string>;
  messageId?: string;
  sizeEstimate?: number;
  subject?: string;
  text?: string;
  textAsHtml?: string;
  threadId?: string;
  to?: {
    html?: string;
    text?: string;
    value?: Array<{
      address?: string;
      name?: string;
    }>;
  };
};

export type GmailV2MessageGetNode = {
  type: 'n8n-nodes-base.gmail';
  version: 2;
  config: NodeConfig<GmailV2MessageGetParams> & { credentials?: Credentials };
  output?: Items<GmailV2MessageGetOutput>;
};